module safe_rocket(\n    input [1:0] size_a,\n    input [7:0] ax0, ay0,\n    input [7:0] ax1, ay1,\n    input [7:0] ax2, ay2,\n    input [7:0] ax3, ay3,\n    input [1:0] size_b,\n    input [7:0] bx0, by0,\n    input [7:0] bx1, by1,\n    input [7:0] bx2, by2,\n    input [7:0] bx3, by3,\n    output safe\n);\n    \n    // Size match check\n    wire sizes_match = (size_a == size_b);\n    \n    // Size 2 distance squares\n    wire [17:0] dist2_a = ((ax1 - ax0)*(ax1 - ax0)) + ((ay1 - ay0)*(ay1 - ay0));\n    wire [17:0] dist2_b = ((bx1 - bx0)*(bx1 - bx0)) + ((by1 - by0)*(by1 - by0));\n    \n    // Translated coordinates\n    wire signed [8:0] tx_a1 = {1'b0, ax1} - {1'b0, ax0};\n    wire signed [8:0] ty_a1 = {1'b0, ay1} - {1'b0, ay0};\n    wire signed [8:0] tx_a2 = {1'b0, ax2} - {1'b0, ax0};\n    wire signed [8:0] ty_a2 = {1'b0, ay2} - {1'b0, ay0};\n    wire signed [8:0] tx_a3 = {1'b0, ax3} - {1'b0, ax0};\n    wire signed [8:0] ty_a3 = {1'b0, ay3} - {1'b0, ay0};\n    \n    wire signed [8:0] tx_b1 = {1'b0, bx1} - {1'b0, bx0};\n    wire signed [8:0] ty_b1 = {1'b0, by1} - {1'b0, by0};\n    wire signed [8:0] tx_b2 = {1'b0, bx2} - {1'b0, bx0};\n    wire signed [8:0] ty_b2 = {1'b0, by2} - {1'b0, by0};\n    wire signed [8:0] tx_b3 = {1'b0, bx3} - {1'b0, bx0};\n    wire signed [8:0] ty_b3 = {1'b0, by3} - {1'b0, by0};\n    \n    // Polygon A edge vectors\n    wire signed [8:0] edge_ax0 = tx_a1;\n    wire signed [8:0] edge_ay0 = ty_a1;\n    wire signed [8:0] edge_ax1 = tx_a2 - tx_a1;\n    wire signed [8:0] edge_ay1 = ty_a2 - ty_a1;\n    wire signed [8:0] edge_ax2 = (size_a == 2'd3) ? -tx_a2 : (size_a == 2'd4) ? (tx_a3 - tx_a2) : 9'd0;\n    wire signed [8:0] edge_ay2 = (size_a == 2'd3) ? -ty_a2 : (size_a == 2'd4) ? (ty_a3 - ty_a2) : 9'd0;\n    wire signed [8:0] edge_ax3 = (size_a == 2'd4) ? -tx_a3 : 9'd0;\n    wire signed [8:0] edge_ay3 = (size_a == 2'd4) ? -ty_a3 : 9'd0;\n    \n    // Polygon B edge vectors\n    wire signed [8:0] edge_bx0 = tx_b1;\n    wire signed [8:0] edge_by0 = ty_b1;\n    wire signed [8:0] edge_bx1 = tx_b2 - tx_b1;\n    wire signed [8:0] edge_by1 = ty_b2 - ty_b1;\n    wire signed [8:0] edge_bx2 = (size_b == 2'd3) ? -tx_b2 : (size_b == 2'd4) ? (tx_b3 - tx_b2) : 9'd0;\n    wire signed [8:0] edge_by2 = (size_b == 2'd3) ? -ty_b2 : (size_b == 2'd4) ? (ty_b3 - ty_b2) : 9'd0;\n    wire signed [8:0] edge_bx3 = (size_b == 2'd4) ? -tx_b3 : 9'd0;\n    wire signed [8:0] edge_by3 = (size_b == 2'd4) ? -ty_b3 : 9'd0;\n    \n    // Next edge vectors (A)\n    wire signed [8:0] next_ax0 = edge_ax1;\n    wire signed [8:0] next_ay0 = edge_ay1;\n    wire signed [8:0] next_ax1 = edge_ax2;\n    wire signed [8:0] next_ay1 = edge_ay2;\n    wire signed [8:0] next_ax2 = (size_a == 2'd3) ? edge_ax0 : edge_ax3;\n    wire signed [8:0] next_ay2 = (size_a == 2'd3) ? edge_ay0 : edge_ay3;\n    wire signed [8:0] next_ax3 = edge_ax0;\n    wire signed [8:0] next_ay3 = edge_ay0;\n    \n    // Next edge vectors (B)\n    wire signed [8:0] next_bx0 = edge_bx1;\n    wire signed [8:0] next_by0 = edge_by1;\n    wire signed [8:0] next_bx1 = edge_bx2;\n    wire signed [8:0] next_by1 = edge_by2;\n    wire signed [8:0] next_bx2 = (size_b == 2'd3) ? edge_bx0 : edge_bx3;\n    wire signed [8:0] next_by2 = (size_b == 2'd3) ? edge_by0 : edge_by3;\n    wire signed [8:0] next_bx3 = edge_bx0;\n    wire signed [8:0] next_by3 = edge_by0;\n    \n    // Edge features A\n    wire [17:0] len2_a0 = edge_ax0 * edge_ax0 + edge_ay0 * edge_ay0;\n    wire [17:0] len2_a1 = edge_ax1 * edge_ax1 + edge_ay1 * edge_ay1;\n    wire [17:0] len2_a2 = edge_ax2 * edge_ax2 + edge_ay2 * edge_ay2;\n    wire [17:0] len2_a3 = edge_ax3 * edge_ax3 + edge_ay3 * edge_ay3;\n    \n    wire signed [17:0] dot_a0 = edge_ax0 * next_ax0 + edge_ay0 * next_ay0;\n    wire signed [17:0] dot_a1 = edge_ax1 * next_ax1 + edge_ay1 * next_ay1;\n    wire signed [17:0] dot_a2 = edge_ax2 * next_ax2 + edge_ay2 * next_ay2;\n    wire signed [17:0] dot_a3 = edge_ax3 * next_ax3 + edge_ay3 * next_ay3;\n    \n    wire signed [17:0] cross_a0 = edge_ax0 * next_ay0 - edge_ay0 * next_ax0;\n    wire signed [17:0] cross_a1 = edge_ax1 * next_ay1 - edge_ay1 * next_ax1;\n    wire signed [17:0] cross_a2 = edge_ax2 * next_ay2 - edge_ay2 * next_ax2;\n    wire signed [17:0] cross_a3 = edge_ax3 * next_ay3 - edge_ay3 * next_ax3;\n    \n    // Edge features B\n    wire [17:0] len2_b0 = edge_bx0 * edge_bx0 + edge_by0 * edge_by0;\n    wire [17:0] len2_b1 = edge_bx1 * edge_bx1 + edge_by1 * edge_by1;\n    wire [17:0] len2_b2 = edge_bx2 * edge_bx2 + edge_by2 * edge_by2;\n    wire [17:0] len2_b3 = edge_bx3 * edge_bx3 + edge_by3 * edge_by3;\n    \n    wire signed [17:0] dot_b0 = edge_bx0 * next_bx0 + edge_by0 * next_by0;\n    wire signed [17:0] dot_b1 = edge_bx1 * next_bx1 + edge_by1 * next_by1;\n    wire signed [17:0] dot_b2 = edge_bx2 * next_bx2 + edge_by2 * next_by2;\n    wire signed [17:0] dot_b3 = edge_bx3 * next_bx3 + edge_by3 * next_by3;\n    \n    wire signed [17:0] cross_b0 = edge_bx0 * next_by0 - edge_by0 * next_bx0;\n    wire signed [17:0] cross_b1 = edge_bx1 * next_by1 - edge_by1 * next_bx1;\n    wire signed [17:0] cross_b2 = edge_bx2 * next_by2 - edge_by2 * next_bx2;\n    wire signed [17:0] cross_b3 = edge_bx3 * next_by3 - edge_by3 * next_bx3;\n    \n    // Size 3 matching\n    wire match_s3_0 = (len2_a0 == len2_b0) && (dot_a0 == dot_b0) && (cross_a0 == cross_b0) &&\n                     (len2_a1 == len2_b1) && (dot_a1 == dot_b1) && (cross_a1 == cross_b1) &&\n                     (len2_a2 == len2_b2) && (dot_a2 == dot_b2) && (cross_a2 == cross_b2);\n    wire match_s3_1 = (len2_a0 == len2_b1) && (dot_a0 == dot_b1) && (cross_a0 == cross_b1) &&\n                     (len2_a1 == len2_b2) && (dot_a1 == dot_b2) && (cross_a1 == cross_b2) &&\n                     (len2_a2 == len2_b0) && (dot_a2 == dot_b0) && (cross_a2 == cross_b0);\n    wire match_s3_2 = (len2_a0 == len2_b2) && (dot_a0 == dot_b2) && (cross_a0 == cross_b2) &&\n                     (len2_a1 == len2_b0) && (dot_a1 == dot_b0) && (cross_a1 == cross_b0) &&\n                     (len2_a2 == len2_b1) && (dot_a2 == dot_b1) && (cross_a2 == cross_b1);\n    wire matches_s3 = match_s3_0 || match_s3_1 || match_s3_2;\n    \n    // Size 4 matching\n    wire match_s4_0 = (len2_a0 == len2_b0) && (dot_a0 == dot_b0) && (cross_a0 == cross_b0) &&\n                     (len2_a1 == len2_b1) && (dot_a1 == dot_b1) && (cross_a1 == cross_b1) &&\n                     (len2_a2 == len2_b2) && (dot_a2 == dot_b2) && (cross_a2 == cross_b2) &&\n                     (len2_a3 == len2_b3) && (dot_a3 == dot_b3) && (cross_a3 == cross_b3);\n    wire match_s4_1 = (len2_a0 == len2_b1) && (dot_a0 == dot_b1) && (cross_a0 == cross_b1) &&\n                     (len2_a1 == len2_b2) && (dot_a1 == dot_b2) && (cross_a1 == cross_b2) &&\n                     (len2_a2 == len2_b3) && (dot_a2 == dot_b3) && (cross_a2 == cross_b3) &&\n                     (len2_a3 == len2_b0) && (dot_a3 == dot_b0) && (cross_a3 == cross_b0);\n    wire match_s4_2 = (len2_a0 == len2_b2) && (dot_a0 == dot_b2) && (cross_a0 == cross_b2) &&\n                     (len2_a1 == len2_b3) && (dot_a1 == dot_b3) && (cross_a1 == cross_b3) &&\n                     (len2_a2 == len2_b0) && (dot_a2 == dot_b0) && (cross_a2 == cross_b0) &&\n                     (len2_a3 == len2_b1) && (dot_a3 == dot_b1) && (cross_a3 == cross_b1);\n    wire match_s4_3 = (len2_a0 == len2_b3) && (dot_a0 == dot_b3) && (cross_a0 == cross_b3) &&\n                     (len2_a1 == len2_b0) && (dot_a1 == dot_b0) && (cross_a1 == cross_b0) &&\n                     (len2_a2 == len2_b1) && (dot_a2 == dot_b1) && (cross_a2 == cross_b1) &&\n                     (len2_a3 == len2_b2) && (dot_a3 == dot_b2) && (cross_a3 == cross_b2);\n    wire matches_s4 = match_s4_0 || match_s4_1 || match_s4_2 || match_s4_3;\n    \n    // Final decision\n    assign safe = sizes_match ?\n                  (size_a == 2'd2) ? (dist2_a == dist2_b) :\n                  (size_a == 2'd3) ? matches_s3 :\n                  (size_a == 2'd4) ? matches_s4 : 1'b0 :\n                  1'b0;\nendmodule